{
  "name": "Flask网络服务",
  "name_en": "Flask Web Service",
  "manufacturer": "",
  "description": "用于管理基于 Flask 的 HTTP 网络服务的软件组件，可注册 API 路由并启动或停止服务器，常用于实验系统的远程控制与接口集成。它不是物理实验仪器。",
  "description_en": "A software component that manages a Flask-based HTTP web service. It can register API routes and start or stop the server, and is commonly used for remote control and interface integration in lab systems. It is not a physical laboratory instrument.",
  "actions": [
    {
      "action_name": "auto-register_routes",
      "description": "注册 API 路由处理器。",
      "description_en": "Register API route handlers."
    },
    {
      "action_name": "auto-start",
      "description": "启动 Flask HTTP 服务。",
      "description_en": "Start the Flask HTTP service."
    },
    {
      "action_name": "auto-stop",
      "description": "停止 Flask HTTP 服务。",
      "description_en": "Stop the Flask HTTP service."
    },
    {
      "action_name": "get_app",
      "description": "获取 Flask 应用实例。",
      "description_en": "Get the Flask application instance."
    }
  ],
  "tag_hints": [
    "Flask web server",
    "HTTP API",
    "route registration",
    "service lifecycle control",
    "remote experiment interface"
  ]
}

